#[derive(Clone, PartialEq, Debug)]
struct VaultState {
    reserve: i64,
    paused: i64,
    agent_root: [u8; 32],
    policy_nonce: i64,
}

#[derive(Clone, Copy, PartialEq, Debug)]
enum Profile {
    /// contracts/PolicyVault.v0.7-payment.sil (the production candidate)
    RootedV7,
    /// contracts/PolicyVault.v0.5.sil (FROZEN — read-only comparison baseline)
    FrozenV5,
}

fn profile_src(p: Profile) -> &'static str {
    match p {
        Profile::RootedV7 => src_vault_raw(),
        Profile::FrozenV5 => src_v5_raw(),
    }
}

/// Exact-live-state templating — the same anchors the v0.5 production suite
/// uses, and the delta generator never touches them.
fn vault_templated(src: &str, s: &VaultState) -> String {
    let mut src = src.to_string();
    let mut r = |from: String, to: String| {
        assert!(src.contains(&from), "anchor missing: {from}");
        src = src.replacen(&from, &to, 1);
    };
    r("int feeReserve = initFeeReserve;".into(), format!("int feeReserve = {};", s.reserve));
    r("int paused = 0;".into(), format!("int paused = {};", s.paused));
    r("byte[32] agentRoot = initAgentRoot;".into(), format!("byte[32] agentRoot = 0x{};", hx(&s.agent_root)));
    r("int policyNonce = 0;".into(), format!("int policyNonce = {};", s.policy_nonce));
    src
}

#[derive(Clone)]
struct TokenPin {
    covid: Hash,
    hash: [u8; 32],
    prefix_len: i64,
    state_len: i64,
    suffix_len: i64,
}
#[derive(Clone)]
struct RootPin {
    covid: Hash,
    hash: [u8; 32],
    prefix_len: i64,
    state_len: i64,
    suffix_len: i64,
}

fn compile_vault(p: Profile, tok: &TokenPin, root: &RootPin, recovery_pk: &[u8; 32], s: &VaultState) -> CompiledContract<'static> {
    compile_vault_from(profile_src(p), p, tok, root, recovery_pk, s)
}
fn compile_vault_from(
    raw: &str,
    p: Profile,
    tok: &TokenPin,
    root: &RootPin,
    recovery_pk: &[u8; 32],
    s: &VaultState,
) -> CompiledContract<'static> {
    let src: &'static str = leak(vault_templated(raw, s));
    let mut args: Vec<Expr<'static>> = vec![];
    if p == Profile::FrozenV5 {
        args.push(Expr::bytes(recovery_pk.to_vec())); // the frozen v0.5 `pubkey owner`
    }
    args.push(Expr::bytes(VAULT_ID.to_vec()));
    args.push(Expr::bytes(DESCRIPTOR_HASH.to_vec()));
    args.push(Expr::bytes(tok.covid.as_bytes().to_vec()));
    args.push(Expr::bytes(tok.hash.to_vec()));
    args.push(Expr::int(tok.prefix_len));
    args.push(Expr::int(tok.state_len));
    args.push(Expr::int(tok.suffix_len));
    if p != Profile::FrozenV5 {
        args.push(Expr::bytes(root.covid.as_bytes().to_vec()));
        args.push(Expr::bytes(root.hash.to_vec()));
        args.push(Expr::int(root.prefix_len));
        args.push(Expr::int(root.state_len));
        args.push(Expr::int(root.suffix_len));
        args.push(Expr::bytes(recovery_pk.to_vec()));
    }
    args.push(Expr::bytes(s.agent_root.to_vec()));
    args.push(Expr::int(s.reserve));
    compile_contract(src, &args, CompileOptions::default()).unwrap_or_else(|e| panic!("compile {p:?}: {e:?}"))
}

fn vault_state_arg(s: &VaultState) -> Expr<'static> {
    struct_object(vec![
        ("boundVaultId", Expr::bytes(VAULT_ID.to_vec())),
        ("feeReserve", Expr::int(s.reserve)),
        ("paused", Expr::int(s.paused)),
        ("agentRoot", Expr::bytes(s.agent_root.to_vec())),
        ("policyNonce", Expr::int(s.policy_nonce)),
    ])
}

fn compile_kcc20(owner: [u8; 32], ty: u8, amount: i64, minter: bool, max_cov: i64) -> CompiledContract<'static> {
    compile_contract(
        src_kcc20(),
        &[Expr::bytes(owner.to_vec()), Expr::int(amount), Expr::byte(ty), Expr::bool(minter), Expr::int(max_cov), Expr::int(max_cov)],
        CompileOptions::default(),
    )
    .expect("compile kcc20")
}
fn kcc20_state<'i>(owner: [u8; 32], ty: u8, amount: i64, minter: bool) -> Expr<'i> {
    struct_object(vec![
        ("ownerIdentifier", Expr::bytes(owner.to_vec())),
        ("identifierType", Expr::byte(ty)),
        ("amount", Expr::int(amount)),
        ("isMinter", Expr::bool(minter)),
    ])
}

fn token_pin(covid: Hash) -> TokenPin {
    let sample = compile_kcc20(COV_VAULT.as_bytes().try_into().unwrap(), IDENTIFIER_COVENANT_ID, PREV_TOKEN_AMOUNT, false, 2);
    let t = template_of(&sample);
    TokenPin { covid, hash: t.hash, prefix_len: t.prefix.len() as i64, state_len: t.state_len as i64, suffix_len: t.suffix.len() as i64 }
}
fn root_pin(covid: Hash, tmpl: &RootTemplate) -> RootPin {
    let sample = compile_root(&RootState::with(1, 1, 1, 0), tmpl);
    let t = template_of(&sample);
    RootPin { covid, hash: t.hash, prefix_len: t.prefix.len() as i64, state_len: t.state_len as i64, suffix_len: t.suffix.len() as i64 }
}

